import sys
from datetime import datetime

def parse_time(time_str):
    h, m = map(int, time_str.split(':'))
    return datetime.combine(datetime.min, datetime.min.time()) + timedelta(hours=h, minutes=m)


def main():
    bookings = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "book":
            bid, room, day, start, end = parts[1:]
            start_time = parse_time(start)
            end_time = parse_time(end)
            if end_time <= start_time:
                print("INVALID", bid)
                continue
            conflict = None
            for other_bid, other_room, other_day, other_start, other_end in bookings:
                if other_room == room and other_day == day and other_start <= end_time and other_end >= start_time:
                    conflict = other_bid
                    break
            if conflict:
                print("REJECT", bid, conflict)
            else:
                bookings.append((bid, room, day, start_time, end_time))
                print("ACCEPT", bid)
        elif parts[0] == "cancel":
            new_bookings = [b for b in bookings if b[0] != parts[1]]
            bookings = new_bookings
            print("CANCELLED", parts[1])
    rooms = {}
    for bid, room, day, start_time, end_time in bookings:
        rooms[room] = rooms.get(room, 0) + 1
    for room in sorted(rooms):
        active_bookings = [b for b in bookings if b[2] == day and b[1] == room]
        total_minutes = sum((end_time - start_time).total_seconds() / 60 for start_time, end_time in zip(
            [b[3] for b in active_bookings], [b[4] for b in active_bookings]
        ))
        hours = int(total_minutes // 60)
        minutes = int(total_minutes % 60)
        print(f"{room} {len(active_bookings)} {f'{hours}:{minutes:02d}'}")


if __name__ == "__main__":
    main()
